/**
 * zod schema definition for the entity MJ: AI Model Costs
 */
export const MJAIModelCostSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    ModelID: z.string().describe(`
        * * Field Name: ModelID
        * * Display Name: Model
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Models (vwAIModels.ID)`),
    VendorID: z.string().describe(`
        * * Field Name: VendorID
        * * Display Name: Vendor
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Vendors (vwAIVendors.ID)`),
    StartedAt: z.date().nullable().describe(`
        * * Field Name: StartedAt
        * * Display Name: Started At
        * * SQL Data Type: datetimeoffset
        * * Default Value: sysdatetimeoffset()
        * * Description: Date and time with timezone when this pricing became effective. NULL disables temporal tracking. Defaults to current UTC time when record is created`),
    EndedAt: z.date().nullable().describe(`
        * * Field Name: EndedAt
        * * Display Name: Ended At
        * * SQL Data Type: datetimeoffset
        * * Description: Date and time with timezone when this pricing expired or will expire. NULL indicates currently active pricing`),
    Status: z.union([z.literal('Active'), z.literal('Expired'), z.literal('Invalid'), z.literal('Pending')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Expired
    *   * Invalid
    *   * Pending
        * * Description: Current status of this pricing record. Active=currently in use, Pending=scheduled for future, Expired=no longer valid, Invalid=data error`),
    Currency: z.string().describe(`
        * * Field Name: Currency
        * * Display Name: Currency
        * * SQL Data Type: nchar(3)
        * * Description: ISO 4217 three-letter currency code (e.g., USD, EUR, GBP) in uppercase`),
    PriceTypeID: z.string().describe(`
        * * Field Name: PriceTypeID
        * * Display Name: Price Type
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Model Price Types (vwAIModelPriceTypes.ID)
        * * Default Value: ECE2BCB7-C854-4BF7-A517-D72793A40652
        * * Description: DEPRECATED — descriptive only; nothing prices, filters or branches on it. The authority on what a cost row measures is UnitTypeID -> AIModelPriceUnitType.UsageTypeID. Retained only so existing configurations still validate and historical spCreateAIModelCost calls keep working; do not populate it for new cost rows.`),
    InputPricePerUnit: z.number().describe(`
        * * Field Name: InputPricePerUnit
        * * Display Name: Input Price Per Unit
        * * SQL Data Type: decimal(18, 8)
        * * Description: Price per unit for input tokens/requests. Must be non-negative. Precision allows for micro-pricing scenarios`),
    OutputPricePerUnit: z.number().describe(`
        * * Field Name: OutputPricePerUnit
        * * Display Name: Output Price Per Unit
        * * SQL Data Type: decimal(18, 8)
        * * Description: Price per unit for output tokens/responses. Must be non-negative. Often higher than input pricing`),
    UnitTypeID: z.string().describe(`
        * * Field Name: UnitTypeID
        * * Display Name: Unit Type
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Model Price Unit Types (vwAIModelPriceUnitTypes.ID)`),
    ProcessingType: z.union([z.literal('Batch'), z.literal('Realtime')]).describe(`
        * * Field Name: ProcessingType
        * * Display Name: Processing Type
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Batch
    *   * Realtime
        * * Description: Processing method that affects pricing. Realtime=immediate response, Batch=delayed processing often with discounts`),
    Comments: z.string().nullable().describe(`
        * * Field Name: Comments
        * * Display Name: Comments
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional notes about pricing context, source, special conditions, or vendor-specific details`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    CacheReadPricePerUnit: z.number().nullable().describe(`
        * * Field Name: CacheReadPricePerUnit
        * * Display Name: Cache Read Price Per Unit
        * * SQL Data Type: decimal(18, 8)
        * * Description: Optional price per unit for input tokens served from the AI provider's prompt cache (cache reads / hits), expressed in the same currency and UnitType (e.g. per 1M tokens) as InputPricePerUnit. When NULL, cache-read tokens are priced at InputPricePerUnit. Cache reads are usually far cheaper than uncached input (e.g. ~0.1x for Anthropic/Gemini, ~0.5x for OpenAI).`),
    CacheWritePricePerUnit: z.number().nullable().describe(`
        * * Field Name: CacheWritePricePerUnit
        * * Display Name: Cache Write Price Per Unit
        * * SQL Data Type: decimal(18, 8)
        * * Description: Optional price per unit for input tokens written to the AI provider's prompt cache (cache writes / creation), expressed in the same currency and UnitType as InputPricePerUnit. When NULL, cache-write tokens are priced at InputPricePerUnit. Populated for providers that bill cache creation separately (e.g. Anthropic, ~1.25x input); leave NULL for providers that do not (OpenAI, Gemini), which also report 0 cache-write tokens.`),
    Model: z.string().nullable().describe(`
        * * Field Name: Model
        * * Display Name: Model Name
        * * SQL Data Type: nvarchar(50)`),
    Vendor: z.string().nullable().describe(`
        * * Field Name: Vendor
        * * Display Name: Vendor Name
        * * SQL Data Type: nvarchar(50)`),
    PriceType: z.string().nullable().describe(`
        * * Field Name: PriceType
        * * Display Name: Price Type Name
        * * SQL Data Type: nvarchar(100)`),
    UnitType: z.string().nullable().describe(`
        * * Field Name: UnitType
        * * Display Name: Unit Type Name
        * * SQL Data Type: nvarchar(100)`),
});

export type MJAIModelCostEntityType = z.infer<typeof MJAIModelCostSchema>;

