/**
 * zod schema definition for the entity MJ: Queries
 */
export const MJQuerySchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    Name: z.string().describe(`
        * * Field Name: Name
        * * Display Name: Name
        * * SQL Data Type: nvarchar(255)`),
    CategoryID: z.string().nullable().describe(`
        * * Field Name: CategoryID
        * * Display Name: Category
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Query Categories (vwQueryCategories.ID)`),
    UserQuestion: z.string().nullable().describe(`
        * * Field Name: UserQuestion
        * * Display Name: User Question
        * * SQL Data Type: nvarchar(MAX)
        * * Description: The natural language question this query answers, used for AI query selection.`),
    Description: z.string().nullable().describe(`
        * * Field Name: Description
        * * Display Name: Description
        * * SQL Data Type: nvarchar(MAX)`),
    SQL: z.string().nullable().describe(`
        * * Field Name: SQL
        * * Display Name: SQL
        * * SQL Data Type: nvarchar(MAX)
        * * Description: The actual SQL query text to execute, may include parameters.`),
    TechnicalDescription: z.string().nullable().describe(`
        * * Field Name: TechnicalDescription
        * * Display Name: Technical Description
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Technical documentation of the query logic, performance considerations, and parameter usage.`),
    OriginalSQL: z.string().nullable().describe(`
        * * Field Name: OriginalSQL
        * * Display Name: Original SQL
        * * SQL Data Type: nvarchar(MAX)
        * * Description: The original SQL before any optimization or modification, kept for reference.`),
    Feedback: z.string().nullable().describe(`
        * * Field Name: Feedback
        * * Display Name: Feedback
        * * SQL Data Type: nvarchar(MAX)
        * * Description: User feedback on query accuracy, performance, or suggested improvements.`),
    Status: z.union([z.literal('Approved'), z.literal('Expired'), z.literal('Pending'), z.literal('Rejected')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(15)
        * * Default Value: Pending
    * * Value List Type: List
    * * Possible Values 
    *   * Approved
    *   * Expired
    *   * Pending
    *   * Rejected`),
    QualityRank: z.number().nullable().describe(`
        * * Field Name: QualityRank
        * * Display Name: Quality Rank
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Value indicating the quality of the query, higher values mean a better quality`),
    ExecutionCostRank: z.number().nullable().describe(`
        * * Field Name: ExecutionCostRank
        * * Display Name: Execution Cost Rank
        * * SQL Data Type: int
        * * Description: Higher numbers indicate more execution overhead/time required. Useful for planning which queries to use in various scenarios.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    UsesTemplate: z.boolean().nullable().describe(`
        * * Field Name: UsesTemplate
        * * Display Name: Uses Template
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: Automatically set to true when the SQL column contains Nunjucks template markers (e.g., {{ paramName }}). This flag is maintained by the QueryEntityServer for performance optimization and discovery purposes. It allows quick filtering of parameterized queries and enables the UI to show parameter inputs only when needed. The system will automatically update this flag when the SQL content changes.`),
    AuditQueryRuns: z.boolean().describe(`
        * * Field Name: AuditQueryRuns
        * * Display Name: Audit Query Runs
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: When true, all executions of this query will be logged to the Audit Log system for tracking and compliance`),
    CacheEnabled: z.boolean().describe(`
        * * Field Name: CacheEnabled
        * * Display Name: Cache Enabled
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: When true, enables query result caching. Caching behavior depends on CacheValidationSQL: (1) If CacheValidationSQL is NULL, uses simple server-side TTL caching based on CacheTTLMinutes - results are cached on the server and expire after the TTL period. (2) If CacheValidationSQL is set, enables smart client-side caching with freshness validation - client sends cache fingerprint (maxUpdatedAt + rowCount) to server, server validates using CacheValidationSQL and returns 'current' (use cached) or 'stale' (with fresh data). Smart caching provides real-time accuracy while minimizing data transfer.`),
    CacheTTLMinutes: z.number().nullable().describe(`
        * * Field Name: CacheTTLMinutes
        * * Display Name: Cache TTL (Minutes)
        * * SQL Data Type: int
        * * Description: Time-to-live in minutes for cached query results. NULL uses default TTL.`),
    CacheMaxSize: z.number().nullable().describe(`
        * * Field Name: CacheMaxSize
        * * Display Name: Cache Max Size
        * * SQL Data Type: int
        * * Description: Maximum number of cached result sets for this query. NULL uses default size limit.`),
    EmbeddingVector: z.string().nullable().describe(`
        * * Field Name: EmbeddingVector
        * * Display Name: Embedding Vector
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional JSON-serialized embedding vector for the query, used for similarity search and query analysis`),
    EmbeddingModelID: z.string().nullable().describe(`
        * * Field Name: EmbeddingModelID
        * * Display Name: Embedding Model
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Models (vwAIModels.ID)
        * * Description: The AI Model used to generate the embedding vector for this query. Required for vector similarity comparisons.`),
    CacheValidationSQL: z.string().nullable().describe(`
        * * Field Name: CacheValidationSQL
        * * Display Name: Cache Validation SQL
        * * SQL Data Type: nvarchar(MAX)
        * * Description: SQL query used to validate cache freshness for smart caching. When set (and CacheEnabled=true), enables smart cache validation instead of simple TTL expiration. This query MUST return exactly two columns: MaxUpdatedAt (datetime/datetimeoffset) and TotalRows (int). The query has access to the same Nunjucks parameters as the main query SQL. When NULL, caching uses TTL-only behavior based on CacheTTLMinutes. Example: SELECT MAX(__mj_UpdatedAt) AS MaxUpdatedAt, COUNT(*) AS TotalRows FROM Orders WHERE Status = '{{ status }}'`),
    SQLDialectID: z.string().describe(`
        * * Field Name: SQLDialectID
        * * Display Name: SQL Dialect
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: SQL Dialects (vwSQLDialects.ID)
        * * Default Value: 1F203987-A37B-4BC1-85B3-BA50DC33C3E0
        * * Description: The SQL dialect that the SQL column is written in. Defaults to T-SQL for backward compatibility.`),
    Reusable: z.boolean().describe(`
        * * Field Name: Reusable
        * * Display Name: Is Reusable
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: When true, this query can be referenced by other queries using composition syntax. Only queries that are both Reusable and Approved can be composed into other queries.`),
    ExternalDataSourceID: z.string().nullable().describe(`
        * * Field Name: ExternalDataSourceID
        * * Display Name: External Data Source ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: External Data Sources (vwExternalDataSources.ID)`),
    IsMaterialized: z.boolean().describe(`
        * * Field Name: IsMaterialized
        * * Display Name: Is Materialized
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: Author's declared intent that this Query should be materialized. CodeGen scans for IsMaterialized = 1 and, if the query qualifies (§9/§10), materializes it. The authoritative state lives on the linked MJ: Materialized Results row (found via the MaterializedResultQuery join table).`),
    Configuration: z.any().nullable().describe(`
        * * Field Name: Configuration
        * * Display Name: Configuration
        * * SQL Data Type: nvarchar(MAX)
        * * JSON Type: MJQueryEntity_IQueryConfiguration
        * * Description: Optional JSON configuration bag defining query-level policies and semantic capabilities (shape = IQueryConfiguration). Includes Priority (1-100) for ground-truth ranking in the semantic layer, LogExecution to control query execution logging, AlternativeQuestions for multi-phrasing vector recall, UsageGuidance and WhenNotToUse bounds for AI agents, and DomainScope.`),
    EmbeddingVectorBinary: z.string().nullable().describe(`
        * * Field Name: EmbeddingVectorBinary
        * * Display Name: Embedding Vector Binary
        * * SQL Data Type: varbinary(MAX)
        * * Description: The query embedding as little-endian IEEE-754 float32 bytes (4 bytes per dimension): the compact form of EmbeddingVector. Written alongside EmbeddingVector; readers prefer it and fall back to EmbeddingVector when it is NULL.`),
    ApprovalComments: z.string().nullable().describe(`
        * * Field Name: ApprovalComments
        * * Display Name: Approval Comments
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Reviewer comments recorded with the approval decision, such as the tests the definition passed.`),
    ApprovedByUserID: z.string().nullable().describe(`
        * * Field Name: ApprovedByUserID
        * * Display Name: Approved By User ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Users (vwUsers.ID)
        * * Description: The user who approved this query.`),
    ApprovedAt: z.date().nullable().describe(`
        * * Field Name: ApprovedAt
        * * Display Name: Approved At
        * * SQL Data Type: datetimeoffset
        * * Description: When this query was approved.`),
    ApprovedFingerprint: z.string().nullable().describe(`
        * * Field Name: ApprovedFingerprint
        * * Display Name: Approved Fingerprint
        * * SQL Data Type: nvarchar(100)
        * * Description: SHA-256 fingerprint of the definition that was approved: its SQL, dialect variants and parameter contract. The approval is current only while this matches the fingerprint of the current definition.`),
    ExtractedSQLHash: z.string().nullable().describe(`
        * * Field Name: ExtractedSQLHash
        * * Display Name: Extracted SQL Hash
        * * SQL Data Type: nvarchar(64)
        * * Description: Hash of the platform SQL and dialect the query's child rows (fields, parameters, entities, dependencies) were last extracted from. NULL means the query has never been extracted by the current extraction service. A value that differs from the current SQL's hash means the rows may be stale.`),
    ExtractionStatus: z.union([z.literal('Error'), z.literal('OK'), z.literal('Skipped'), z.literal('Warning')]).nullable().describe(`
        * * Field Name: ExtractionStatus
        * * Display Name: Extraction Status
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Error
    *   * OK
    *   * Skipped
    *   * Warning
        * * Description: Outcome of the last extraction run. "OK" means all facts were extracted. "Warning" means extraction succeeded with findings (see ExtractionMessage). "Error" means the database server could not describe the query, so existing rows were kept. "Skipped" means the facts could not be checked, for example for queries on an external data source. NULL means never extracted.`),
    ExtractionMessage: z.string().nullable().describe(`
        * * Field Name: ExtractionMessage
        * * Display Name: Extraction Message
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Diagnostics from the last extraction run: validation findings, authored parameters no longer present in the SQL, describe errors, and output drift on queries with role-based permissions.`),
    Category: z.string().nullable().describe(`
        * * Field Name: Category
        * * Display Name: Category Name
        * * SQL Data Type: nvarchar(50)`),
    EmbeddingModel: z.string().nullable().describe(`
        * * Field Name: EmbeddingModel
        * * Display Name: Embedding Model Name
        * * SQL Data Type: nvarchar(50)`),
    SQLDialect: z.string().nullable().describe(`
        * * Field Name: SQLDialect
        * * Display Name: SQL Dialect Name
        * * SQL Data Type: nvarchar(100)`),
    ExternalDataSource: z.string().nullable().describe(`
        * * Field Name: ExternalDataSource
        * * Display Name: External Data Source
        * * SQL Data Type: nvarchar(100)`),
    ApprovedByUser: z.string().nullable().describe(`
        * * Field Name: ApprovedByUser
        * * Display Name: Approved By User
        * * SQL Data Type: nvarchar(100)`),
});

