export type MJScheduledJobTypeEntityType = z.infer<typeof MJScheduledJobTypeSchema>;

/**
 * zod schema definition for the entity MJ: Scheduled Jobs
 */
export const MJScheduledJobSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    JobTypeID: z.string().describe(`
        * * Field Name: JobTypeID
        * * Display Name: Job Type ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Scheduled Job Types (vwScheduledJobTypes.ID)`),
    Name: z.string().describe(`
        * * Field Name: Name
        * * Display Name: Name
        * * SQL Data Type: nvarchar(200)
        * * Description: Human-readable name for this scheduled job. Should clearly identify what the job does.`),
    Description: z.string().nullable().describe(`
        * * Field Name: Description
        * * Display Name: Description
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Detailed description of the job's purpose, what it does, and any important notes about its execution.`),
    CronExpression: z.string().describe(`
        * * Field Name: CronExpression
        * * Display Name: Cron Expression
        * * SQL Data Type: nvarchar(120)
        * * Description: Cron expression defining when the job should execute (e.g., "0 30 9 * * MON-FRI" for weekdays at 9:30 AM). Uses standard cron syntax with seconds precision.`),
    Timezone: z.string().describe(`
        * * Field Name: Timezone
        * * Display Name: Timezone
        * * SQL Data Type: nvarchar(64)
        * * Default Value: UTC
        * * Description: IANA timezone identifier for interpreting the cron expression (e.g., "America/Chicago", "UTC"). Ensures consistent scheduling across different server locations.`),
    StartAt: z.date().nullable().describe(`
        * * Field Name: StartAt
        * * Display Name: Start At
        * * SQL Data Type: datetimeoffset
        * * Description: Optional start date/time for when this schedule becomes active. Job will not execute before this time. NULL means active immediately upon creation.`),
    EndAt: z.date().nullable().describe(`
        * * Field Name: EndAt
        * * Display Name: End At
        * * SQL Data Type: datetimeoffset
        * * Description: Optional end date/time for when this schedule expires. Job will not execute after this time. NULL means no expiration.`),
    Status: z.union([z.literal('Active'), z.literal('Disabled'), z.literal('Expired'), z.literal('Paused'), z.literal('Pending')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Pending
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Disabled
    *   * Expired
    *   * Paused
    *   * Pending
        * * Description: Current status of the schedule. Pending=created but not yet active, Active=currently running on schedule, Paused=temporarily stopped, Disabled=manually disabled, Expired=past EndAt date.`),
    Configuration: z.string().nullable().describe(`
        * * Field Name: Configuration
        * * Display Name: Configuration
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Job-type specific configuration stored as JSON. Schema is defined by the ScheduledJobType plugin. For Agents: includes AgentID, StartingPayload, InitialMessage, etc. For Actions: includes ActionID and parameter mappings.`),
    OwnerUserID: z.string().nullable().describe(`
        * * Field Name: OwnerUserID
        * * Display Name: Owner User ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Users (vwUsers.ID)
        * * Description: User who owns this schedule. Used as the execution context if no specific user is configured in the job-specific configuration.`),
    LastRunAt: z.date().nullable().describe(`
        * * Field Name: LastRunAt
        * * Display Name: Last Run At
        * * SQL Data Type: datetimeoffset
        * * Description: Timestamp of the most recent execution. Updated after each run. Used for monitoring and dashboard displays.`),
    NextRunAt: z.date().nullable().describe(`
        * * Field Name: NextRunAt
        * * Display Name: Next Run At
        * * SQL Data Type: datetimeoffset
        * * Description: Calculated timestamp of when this job should next execute based on the cron expression. Updated after each run. Used by scheduler to determine which jobs are due.`),
    RunCount: z.number().describe(`
        * * Field Name: RunCount
        * * Display Name: Run Count
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Total number of times this schedule has been executed, including both successful and failed runs.`),
    SuccessCount: z.number().describe(`
        * * Field Name: SuccessCount
        * * Display Name: Success Count
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Number of times this schedule has executed successfully (Success = true in ScheduledJobRun).`),
    FailureCount: z.number().describe(`
        * * Field Name: FailureCount
        * * Display Name: Failure Count
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Number of times this schedule has executed but failed (Success = false in ScheduledJobRun).`),
    NotifyOnSuccess: z.boolean().describe(`
        * * Field Name: NotifyOnSuccess
        * * Display Name: Notify On Success
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: Whether to send notifications when the job completes successfully.`),
    NotifyOnFailure: z.boolean().describe(`
        * * Field Name: NotifyOnFailure
        * * Display Name: Notify On Failure
        * * SQL Data Type: bit
        * * Default Value: 1
        * * Description: Whether to send notifications when the job fails. Defaults to true for alerting on failures.`),
    NotifyUserID: z.string().nullable().describe(`
        * * Field Name: NotifyUserID
        * * Display Name: Notify User ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Users (vwUsers.ID)
        * * Description: User to notify about job execution results. If NULL and notifications are enabled, falls back to OwnerUserID.`),
    NotifyViaEmail: z.boolean().describe(`
        * * Field Name: NotifyViaEmail
        * * Display Name: Notify Via Email
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: Whether to send email notifications. Requires NotifyOnSuccess or NotifyOnFailure to also be enabled.`),
    NotifyViaInApp: z.boolean().describe(`
        * * Field Name: NotifyViaInApp
        * * Display Name: Notify Via In-App
        * * SQL Data Type: bit
        * * Default Value: 1
        * * Description: Whether to send in-app notifications. Requires NotifyOnSuccess or NotifyOnFailure to also be enabled. Defaults to true.`),
    LockToken: z.string().nullable().describe(`
        * * Field Name: LockToken
        * * Display Name: Lock Token
        * * SQL Data Type: uniqueidentifier
        * * Description: Unique token used for distributed locking across multiple server instances. Set when a server claims the job for execution. Prevents duplicate executions in multi-server environments.`),
    LockedAt: z.date().nullable().describe(`
        * * Field Name: LockedAt
        * * Display Name: Locked At
        * * SQL Data Type: datetimeoffset
        * * Description: Timestamp when the lock was acquired. Used with ExpectedCompletionAt to detect stale locks from crashed server instances.`),
    LockedByInstance: z.string().nullable().describe(`
        * * Field Name: LockedByInstance
        * * Display Name: Locked By Instance
        * * SQL Data Type: nvarchar(255)
        * * Description: Identifier of the server instance that currently holds the lock (e.g., "hostname-12345"). Used for troubleshooting and monitoring which server is executing which job.`),
    ExpectedCompletionAt: z.date().nullable().describe(`
        * * Field Name: ExpectedCompletionAt
        * * Display Name: Expected Completion At
        * * SQL Data Type: datetimeoffset
        * * Description: Expected completion time for the current execution. If current time exceeds this and lock still exists, the lock is considered stale and can be claimed by another instance. Handles crashed server cleanup.`),
    ConcurrencyMode: z.union([z.literal('Concurrent'), z.literal('Queue'), z.literal('Skip')]).describe(`
        * * Field Name: ConcurrencyMode
        * * Display Name: Concurrency Mode
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Skip
    * * Value List Type: List
    * * Possible Values 
    *   * Concurrent
    *   * Queue
    *   * Skip
        * * Description: Controls behavior when a new execution is scheduled while a previous execution is still running. Skip=do not start new execution (default), Queue=wait for current to finish then execute, Concurrent=allow multiple simultaneous executions.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    RunImmediatelyIfNeverRun: z.boolean().describe(`
        * * Field Name: RunImmediatelyIfNeverRun
        * * Display Name: Run Immediately If Never Run
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: When true AND LastRunAt IS NULL, the scheduler sets NextRunAt to now() instead of the next cron tick on initialization, so the job runs on the next polling cycle. Useful for newly-seeded jobs that should not wait up to a full cron interval before their first execution.`),
    MaxRuntimeMinutes: z.number().nullable().describe(`
        * * Field Name: MaxRuntimeMinutes
        * * Display Name: Max Runtime Minutes
        * * SQL Data Type: int
        * * Description: Optional per-job override for the acquire-time lock lease length, in minutes. When set and positive, the engine uses max(default lease, MaxRuntimeMinutes) as the initial ExpectedCompletionAt — so it only ever EXTENDS the default lease, never shrinks it. Intended for jobs whose work is a single long-running call that cannot heartbeat mid-flight (e.g. one slow synchronous action). Jobs that heartbeat via the plugin opt-in pattern do not need this. NULL = use the engine default lease (LeaseTimeoutMinutes). See plans/scheduled-job-engine-heartbeat-lease.md (GH #2749).`),
    MissedRunPolicy: z.union([z.literal('RunAll'), z.literal('RunOnce'), z.literal('Skip')]).describe(`
        * * Field Name: MissedRunPolicy
        * * Display Name: Missed Run Policy
        * * SQL Data Type: nvarchar(20)
        * * Default Value: RunOnce
    * * Value List Type: List
    * * Possible Values 
    *   * RunAll
    *   * RunOnce
    *   * Skip
        * * Description: What this job does about fire times that passed while the scheduler was not running (a deploy, a crash, a sleeping machine). RunOnce (the default) performs a single catch-up run and then resumes the normal schedule — correct for digests, syncs and anything where only the latest state matters, and identical to the behavior every job had before this column existed. RunAll replays each missed occurrence, one per poll tick so a long outage drains gradually rather than dispatching at once — correct for per-period work such as billing or metric snapshots, where skipping a period loses data nothing else recreates. Skip performs no catch-up at all and simply advances to the next future occurrence — correct for work whose value expires, such as a cache warm. A run is only treated as missed when a LATER occurrence has also come due, so a job that merely became due seconds ago is never misclassified; this is evaluated cron-relatively rather than against a fixed grace window, which would misjudge both a per-minute job after a short pause and a monthly job that is a week late.`),
    JobType: z.string().nullable().describe(`
        * * Field Name: JobType
        * * Display Name: Job Type
        * * SQL Data Type: nvarchar(100)`),
    OwnerUser: z.string().nullable().describe(`
        * * Field Name: OwnerUser
        * * Display Name: Owner User
        * * SQL Data Type: nvarchar(100)`),
    NotifyUser: z.string().nullable().describe(`
        * * Field Name: NotifyUser
        * * Display Name: Notify User
        * * SQL Data Type: nvarchar(100)`),
});

export type MJScheduledJobEntityType = z.infer<typeof MJScheduledJobSchema>;

/**
 * zod schema definition for the entity MJ: Schema Info
 */
export const MJSchemaInfoSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    SchemaName: z.string().describe(`
        * * Field Name: SchemaName
        * * Display Name: Schema Name
        * * SQL Data Type: nvarchar(50)
        * * Description: The database schema this information applies to.`),
    EntityIDMin: z.number().describe(`
        * * Field Name: EntityIDMin
        * * Display Name: Entity ID Min
        * * SQL Data Type: int
        * * Description: Field EntityIDMin for entity Schema Info.`),
    EntityIDMax: z.number().describe(`
        * * Field Name: EntityIDMax
        * * Display Name: Entity ID Max
        * * SQL Data Type: int
        * * Description: Field EntityIDMax for entity Schema Info.`),
    Comments: z.string().nullable().describe(`
        * * Field Name: Comments
        * * Display Name: Comments
        * * SQL Data Type: nvarchar(MAX)`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    Description: z.string().nullable().describe(`
        * * Field Name: Description
        * * Display Name: Description
        * * SQL Data Type: nvarchar(MAX)`),
    EntityNamePrefix: z.string().nullable().describe(`
        * * Field Name: EntityNamePrefix
        * * Display Name: Entity Name Prefix
        * * SQL Data Type: nvarchar(25)
        * * Description: Optional prefix to prepend to entity names generated for this schema. For example, setting this to "Committees: " would result in entity names like "Committees: Individuals". Can be overridden by mj.config.cjs NameRulesBySchema settings.`),
    EntityNameSuffix: z.string().nullable().describe(`
        * * Field Name: EntityNameSuffix
        * * Display Name: Entity Name Suffix
        * * SQL Data Type: nvarchar(25)
        * * Description: Optional suffix to append to entity names generated for this schema. Can be overridden by mj.config.cjs NameRulesBySchema settings.`),
    CanonicalSchemaName: z.string().nullable().describe(`
        * * Field Name: CanonicalSchemaName
        * * Display Name: Canonical Schema Name
        * * SQL Data Type: nvarchar(50)
        * * Description: Case-stable canonical schema name, sourced from the app manifest (mj-app.json schema.name). Used in place of SchemaName when deriving the schema prefix for entity ClassName/CodeName and GraphQL type names, so that PostgreSQL installs — whose physical SchemaName is folded to lowercase — still produce PascalCase prefixes matching the published, hand-cased entity packages. NULL means "no override": the prefix falls back to SchemaName (every existing install, the core __mj schema, and SQL Server, where SchemaName is already canonical).`),
});

export type MJSchemaInfoEntityType = z.infer<typeof MJSchemaInfoSchema>;

/**
 * zod schema definition for the entity MJ: Scoped Notification Configs
 */
export const MJScopedNotificationConfigSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    NotificationTypeID: z.string().describe(`
        * * Field Name: NotificationTypeID
        * * Display Name: Notification Type
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: User Notification Types (vwUserNotificationTypes.ID)
        * * Description: The notification type this config is for.`),
    Description: z.string().nullable().describe(`
        * * Field Name: Description
        * * Display Name: Description
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Why the row exists, for the administrator who finds it.`),
    PrimaryScopeEntityID: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeEntityID
        * * Display Name: Primary Scope Entity ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Entities (vwEntities.ID)
        * * Description: The entity of the primary scope record (Applications, Roles, Users, Companies, ...). NULL with PrimaryScopeRecordID NULL = a global row.`),
    PrimaryScopeRecordID: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeRecordID
        * * Display Name: Primary Scope Record ID
        * * SQL Data Type: nvarchar(100)
        * * Description: The record ID within the primary scope entity this config is scoped to. NULL = global. In scope when it is the caller's primary scope record, the recipient, or a role the recipient holds.`),
    SecondaryScopes: z.string().nullable().describe(`
        * * Field Name: SecondaryScopes
        * * Display Name: Secondary Scopes
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON object of additional scope dimensions, e.g. {"origin":"System"}. Every dimension named must match the notice's scope for the row to apply. origin is Person, System (the Owner-type user) or Automation.`),
    InApp: z.union([z.literal('Allow'), z.literal('Deny')]).nullable().describe(`
        * * Field Name: InApp
        * * Display Name: In-App Channel
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Allow
    *   * Deny
        * * Description: The in-app channel: Allow, Deny, or NULL to leave it to the next row.`),
    Email: z.union([z.literal('Allow'), z.literal('Deny')]).nullable().describe(`
        * * Field Name: Email
        * * Display Name: Email Channel
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Allow
    *   * Deny
        * * Description: The email channel: Allow, Deny, or NULL to leave it to the next row.`),
    SMS: z.union([z.literal('Allow'), z.literal('Deny')]).nullable().describe(`
        * * Field Name: SMS
        * * Display Name: SMS Channel
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Allow
    *   * Deny
        * * Description: The SMS channel: Allow, Deny, or NULL to leave it to the next row.`),
    IsLocked: z.boolean().describe(`
        * * Field Name: IsLocked
        * * Display Name: Is Locked
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: When set, a Deny on this row is absorbing: no less specific row and no recipient preference may turn the channel on. The way a notification type's AllowUserPreference caps the recipient today.`),
    Priority: z.number().describe(`
        * * Field Name: Priority
        * * Display Name: Priority
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Tie-break for resolution. Higher wins when two rows tie on scope specificity and neither denies. Default 0.`),
    Status: z.union([z.literal('Active'), z.literal('Archived'), z.literal('Provisional')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Active
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Archived
    *   * Provisional
        * * Description: Lifecycle: Active (live), Provisional (staged; eligible), Archived (excluded from resolution).`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    NotificationType: z.string().nullable().describe(`
        * * Field Name: NotificationType
        * * Display Name: Notification Type Name
        * * SQL Data Type: nvarchar(100)`),
    PrimaryScopeEntity: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeEntity
        * * Display Name: Primary Scope Entity
        * * SQL Data Type: nvarchar(255)`),
});

export type MJScopedNotificationConfigEntityType = z.infer<typeof MJScopedNotificationConfigSchema>;

/**
 * zod schema definition for the entity MJ: Scoped Prompt Configs
 */
export const MJScopedPromptConfigSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    PromptID: z.string().describe(`
        * * Field Name: PromptID
        * * Display Name: Prompt
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Prompts (vwAIPrompts.ID)
        * * Description: The AIPrompt whose run settings this row overrides.`),
    Description: z.string().nullable().describe(`
        * * Field Name: Description
        * * Display Name: Description
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional human-readable note about this override (authoring aid; not sent to the model).`),
    PrimaryScopeEntityID: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeEntityID
        * * Display Name: Primary Scope Entity ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Entities (vwEntities.ID)`),
    PrimaryScopeRecordID: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeRecordID
        * * Display Name: Primary Scope Record ID
        * * SQL Data Type: nvarchar(100)
        * * Description: The record ID within the primary scope entity that this override is scoped to. NULL = global (applies regardless of scope). When set with empty SecondaryScopes, the override is primary-scope-only (e.g. org-level).`),
    SecondaryScopes: z.string().nullable().describe(`
        * * Field Name: SecondaryScopes
        * * Display Name: Secondary Scopes
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON object of additional scope dimensions (e.g. {"ChannelID":"..."}). Empty/NULL with PrimaryScopeRecordID set = primary-scope-only; populated = fully-scoped. Matched (cascading or strict) against the run's SecondaryScopes.`),
    Status: z.union([z.literal('Active'), z.literal('Archived'), z.literal('Provisional')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Active
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Archived
    *   * Provisional
        * * Description: Lifecycle: Active (live), Provisional (staged; eligible but flaggable as not-yet-final), Archived (excluded from resolution). Only Active and Provisional are eligible for resolution.`),
    Priority: z.number().describe(`
        * * Field Name: Priority
        * * Display Name: Priority
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Precedence / tie-break for resolution. Higher wins when two rows tie on scope specificity. Default 0.`),
    ModelID: z.string().nullable().describe(`
        * * Field Name: ModelID
        * * Display Name: Model ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Models (vwAIModels.ID)
        * * Description: Optional model override for this scope. NULL = use the prompt's own model selection. Applied as AIPromptParams.override.modelId.`),
    VendorID: z.string().nullable().describe(`
        * * Field Name: VendorID
        * * Display Name: Vendor ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Vendors (vwAIVendors.ID)
        * * Description: Optional vendor override paired with ModelID (which inference provider serves the model). NULL = let MJ pick. Applied as AIPromptParams.override.vendorId.`),
    ConfigurationID: z.string().nullable().describe(`
        * * Field Name: ConfigurationID
        * * Display Name: Configuration ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Configurations (vwAIConfigurations.ID)
        * * Description: Optional AI Configuration (environment) override for this scope. NULL = inherit. Applied as AIPromptParams.configurationId.`),
    Temperature: z.number().nullable().describe(`
        * * Field Name: Temperature
        * * Display Name: Temperature
        * * SQL Data Type: decimal(3, 2)
        * * Description: Sampling temperature override. NULL = inherit the prompt default. Applied via AIPromptParams.additionalParameters.`),
    TopP: z.number().nullable().describe(`
        * * Field Name: TopP
        * * Display Name: Top P
        * * SQL Data Type: decimal(3, 2)
        * * Description: Nucleus-sampling (top-p) override. NULL = inherit. Applied via additionalParameters.`),
    TopK: z.number().nullable().describe(`
        * * Field Name: TopK
        * * Display Name: Top K
        * * SQL Data Type: int
        * * Description: Top-k sampling override. NULL = inherit. Applied via additionalParameters.`),
    MinP: z.number().nullable().describe(`
        * * Field Name: MinP
        * * Display Name: Min P
        * * SQL Data Type: decimal(3, 2)
        * * Description: Min-p sampling override. NULL = inherit. Applied via additionalParameters.`),
    FrequencyPenalty: z.number().nullable().describe(`
        * * Field Name: FrequencyPenalty
        * * Display Name: Frequency Penalty
        * * SQL Data Type: decimal(3, 2)
        * * Description: Frequency-penalty override. NULL = inherit. Applied via additionalParameters.`),
    PresencePenalty: z.number().nullable().describe(`
        * * Field Name: PresencePenalty
        * * Display Name: Presence Penalty
        * * SQL Data Type: decimal(3, 2)
        * * Description: Presence-penalty override. NULL = inherit. Applied via additionalParameters.`),
    Seed: z.number().nullable().describe(`
        * * Field Name: Seed
        * * Display Name: Seed
        * * SQL Data Type: int
        * * Description: Deterministic sampling seed override. NULL = inherit. Applied via additionalParameters.`),
    StopSequences: z.string().nullable().describe(`
        * * Field Name: StopSequences
        * * Display Name: Stop Sequences
        * * SQL Data Type: nvarchar(1000)
        * * Description: Comma-delimited stop sequences override. NULL = inherit. Applied via additionalParameters.`),
    ResponseFormat: z.union([z.literal('Any'), z.literal('JSON'), z.literal('Markdown'), z.literal('ModelSpecific'), z.literal('Text')]).nullable().describe(`
        * * Field Name: ResponseFormat
        * * Display Name: Response Format
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Any
    *   * JSON
    *   * Markdown
    *   * ModelSpecific
    *   * Text
        * * Description: Response-format override: Any, JSON, Markdown, ModelSpecific, or Text. NULL = inherit. Applied via additionalParameters.`),
    EffortLevel: z.number().nullable().describe(`
        * * Field Name: EffortLevel
        * * Display Name: Effort Level
        * * SQL Data Type: int
        * * Description: Reasoning/effort level override (1-100). NULL = inherit the prompt default. Applied as AIPromptParams.effortLevel.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    Prompt: z.string().nullable().describe(`
        * * Field Name: Prompt
        * * Display Name: Prompt Name
        * * SQL Data Type: nvarchar(255)`),
    PrimaryScopeEntity: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeEntity
        * * Display Name: Primary Scope Entity
        * * SQL Data Type: nvarchar(255)`),
    Model: z.string().nullable().describe(`
        * * Field Name: Model
        * * Display Name: Model
        * * SQL Data Type: nvarchar(50)`),
    Vendor: z.string().nullable().describe(`
        * * Field Name: Vendor
        * * Display Name: Vendor
        * * SQL Data Type: nvarchar(50)`),
    Configuration: z.string().nullable().describe(`
        * * Field Name: Configuration
        * * Display Name: Configuration
        * * SQL Data Type: nvarchar(100)`),
});

export type MJScopedPromptConfigEntityType = z.infer<typeof MJScopedPromptConfigSchema>;

/**
 * zod schema definition for the entity MJ: Scoped Prompt Parts
 */
export const MJScopedPromptPartSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    PromptID: z.string().describe(`
        * * Field Name: PromptID
        * * Display Name: Prompt ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Prompts (vwAIPrompts.ID)`),
    Name: z.string().describe(`
        * * Field Name: Name
        * * Display Name: Name
        * * SQL Data Type: nvarchar(255)
        * * Description: Logical part name (e.g. Personality, Instructions). The OVERRIDE key: per Name within a PromptID, the most-specific scope wins. Distinct Names compose additively.`),
    Role: z.union([z.literal('Assistant'), z.literal('System'), z.literal('User')]).describe(`
        * * Field Name: Role
        * * Display Name: Role
        * * SQL Data Type: nvarchar(20)
        * * Default Value: System
    * * Value List Type: List
    * * Possible Values 
    *   * Assistant
    *   * System
    *   * User
        * * Description: Chat message role this part renders as: System, User, or Assistant. Drives role-faithful assembly (assembled messages drive the model directly, not flattened into one system blob).`),
    Sort: z.number().describe(`
        * * Field Name: Sort
        * * Display Name: Sort
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Final-assembly ordering (ASC). Controls this part's position in the assembled message list. Not used for specificity tie-breaking.`),
    Text: z.string().describe(`
        * * Field Name: Text
        * * Display Name: Text
        * * SQL Data Type: nvarchar(MAX)
        * * Description: The prompt-part text. May contain Nunjucks templating, rendered against the prompt's data context at execution time.`),
    Description: z.string().nullable().describe(`
        * * Field Name: Description
        * * Display Name: Description
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional human-readable note about this part (authoring aid; not sent to the model).`),
    PrimaryScopeEntityID: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeEntityID
        * * Display Name: Primary Scope Entity ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Entities (vwEntities.ID)`),
    PrimaryScopeRecordID: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeRecordID
        * * Display Name: Primary Scope Record ID
        * * SQL Data Type: nvarchar(100)
        * * Description: The record ID within the primary scope entity that this part is scoped to. NULL = global (applies regardless of scope). When set with empty SecondaryScopes, the part is primary-scope-only (e.g. org-level).`),
    SecondaryScopes: z.any().nullable().describe(`
        * * Field Name: SecondaryScopes
        * * Display Name: Secondary Scopes
        * * SQL Data Type: nvarchar(MAX)
        * * JSON Type: MJScopedPromptPartEntity_IAISecondaryScopes
        * * Description: JSON object of additional scope dimensions (e.g. {"ChannelID":"..."}). Empty/NULL with PrimaryScopeRecordID set = primary-scope-only; populated = fully-scoped. Matched (cascading or strict) against the run's SecondaryScopes.`),
    Status: z.union([z.literal('Active'), z.literal('Archived'), z.literal('Provisional')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Active
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Archived
    *   * Provisional
        * * Description: Lifecycle: Active (live), Provisional (staged; eligible but flaggable as not-yet-final), Archived (excluded from resolution). Only Active and Provisional are eligible for resolution.`),
    MergeBehavior: z.union([z.literal('Append'), z.literal('Override')]).describe(`
        * * Field Name: MergeBehavior
        * * Display Name: Merge Behavior
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Override
    * * Value List Type: List
    * * Possible Values 
    *   * Append
    *   * Override
        * * Description: Within a part Name, how this part combines with less-specific same-named parts: 'Override' (default) = the most-specific part replaces the others; 'Append' = all in-scope same-named parts are included additively (ordered by specificity then Priority then Sort). Read by the PromptComponentResolver.`),
    Priority: z.number().describe(`
        * * Field Name: Priority
        * * Display Name: Priority
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Precedence / tie-break for resolution. Higher wins when two same-Name parts tie on scope specificity; also used as a secondary ordering key after Sort. Default 0.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    Prompt: z.string().nullable().describe(`
        * * Field Name: Prompt
        * * Display Name: Prompt
        * * SQL Data Type: nvarchar(255)`),
    PrimaryScopeEntity: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeEntity
        * * Display Name: Primary Scope Entity
        * * SQL Data Type: nvarchar(255)`),
});

export type MJScopedPromptPartEntityType = z.infer<typeof MJScopedPromptPartSchema>;

/**
 * zod schema definition for the entity MJ: Search Execution Logs
 */
export const MJSearchExecutionLogSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    SearchScopeID: z.string().nullable().describe(`
        * * Field Name: SearchScopeID
        * * Display Name: Search Scope
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Search Scopes (vwSearchScopes.ID)
        * * Description: The SearchScope this invocation targeted. NULL for unscoped global search.`),
    UserID: z.string().nullable().describe(`
        * * Field Name: UserID
        * * Display Name: User
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Users (vwUsers.ID)
        * * Description: The User who initiated the search. NULL for system / unauthenticated callers.`),
    AIAgentID: z.string().nullable().describe(`
        * * Field Name: AIAgentID
        * * Display Name: AI Agent
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Agents (vwAIAgents.ID)
        * * Description: The AIAgent identity if the search was invoked from an agent (e.g. ScopedSearchAction). NULL for direct human-initiated searches.`),
    Query: z.string().describe(`
        * * Field Name: Query
        * * Display Name: Query
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Raw query string the user / agent submitted. NVARCHAR(MAX) because some queries are long (full sentences, snippets). Stored verbatim for analytics — do NOT rely on this for permission decisions.`),
    TotalDurationMs: z.number().describe(`
        * * Field Name: TotalDurationMs
        * * Display Name: Total Duration (ms)
        * * SQL Data Type: int
        * * Description: End-to-end search duration in milliseconds, measured at the SearchEngine.search call boundary (provider runs + fusion + rerank + permission filter + enrichment).`),
    ResultCount: z.number().describe(`
        * * Field Name: ResultCount
        * * Display Name: Result Count
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Number of results returned to the caller after permission filtering, deduplication, and score-threshold trimming. Use this as the hit-rate denominator (rows where ResultCount > 0).`),
    RerankerName: z.string().nullable().describe(`
        * * Field Name: RerankerName
        * * Display Name: Reranker Name
        * * SQL Data Type: nvarchar(100)
        * * Description: BaseReRanker.Name of the reranker that ran (e.g. 'Cohere', 'Voyage', 'OpenAI', 'BGE', 'NoopReRanker'). NULL when no rerank stage executed for this invocation.`),
    RerankerCostCents: z.number().nullable().describe(`
        * * Field Name: RerankerCostCents
        * * Display Name: Reranker Cost (Cents)
        * * SQL Data Type: decimal(10, 4)
        * * Description: Total reranker spend in cents for this invocation, populated from the BaseReRanker.CostReporter callback via RerankerBudgetGuard. NULL when no rerank ran or no real-provider cost was incurred (Noop / BGE).`),
    Status: z.union([z.literal('Failure'), z.literal('Forbidden'), z.literal('Success')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Failure
    *   * Forbidden
    *   * Success
        * * Description: Outcome of the search: 'Success' (results returned, possibly empty), 'Failure' (an exception bubbled out — see FailureReason), 'Forbidden' (the caller lacked SearchScopePermission for the requested scope). Constrained by CK_SearchExecutionLog_Status.`),
    FailureReason: z.string().nullable().describe(`
        * * Field Name: FailureReason
        * * Display Name: Failure Reason
        * * SQL Data Type: nvarchar(500)
        * * Description: Short human-readable failure reason when Status = 'Failure' or 'Forbidden'. NULL on success.`),
    ProvidersJSON: z.string().nullable().describe(`
        * * Field Name: ProvidersJSON
        * * Display Name: Providers Breakdown
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON array of per-provider breakdown entries: [{"Provider":"Vector","DurationMs":123,"ResultCount":5,"ErrorMessage":null}, ...]. Used by the analytics dashboard for p50/p95 latency-by-provider charts and to spot consistently slow providers.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    AISkillID: z.string().nullable().describe(`
        * * Field Name: AISkillID
        * * Display Name: AI Skill ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Skills (vwAISkills.ID)
        * * Description: The AI Skill on whose behalf this search ran, or NULL for a search with no active skill. Mirrors AIAgentID: since a skill is a search principal in its own right (AISkill.SearchScopeAccess plus MJ: AI Skill Search Scopes rows can reach a scope the user's own roles do not grant), the log must record which skill was active or the entitlement decision cannot be reconstructed.`),
    PrimaryScopeRecordID: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeRecordID
        * * Display Name: Primary Scope Record ID
        * * SQL Data Type: uniqueidentifier
        * * Description: The tenant this search ran for, taken from SearchContext.PrimaryScopeRecordID. Lets a multi-tenant deployment partition, filter and retain search audit history per customer. NULL for untenanted searches. Named for the existing primary-scope concept rather than OrganizationID because a scope's primary scope may be a Company, Client or Practice.`),
    ScopeDecisionJSON: z.string().nullable().describe(`
        * * Field Name: ScopeDecisionJSON
        * * Display Name: Scope Decision JSON
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Serialized ScopeExplanation recording WHY this search could reach what it reached: the entitlement decision and the grant that produced it, every dimension with its provenance (CallerSupplied / ServerDerived / Default / DiscardedCaller / Absent), and each lane's rendered filter with its active-or-skipped status and reason. Identical in shape to the value returned by SearchEngine.ExplainScope(), so the dry-run an administrator previews before running a search is the same structure the audit log stores afterwards. NULL when the engine did not capture a decision (older writers, or a failure before scope resolution).`),
    SearchScope: z.string().nullable().describe(`
        * * Field Name: SearchScope
        * * Display Name: Search Scope Name
        * * SQL Data Type: nvarchar(200)`),
    User: z.string().nullable().describe(`
        * * Field Name: User
        * * Display Name: User Name
        * * SQL Data Type: nvarchar(100)`),
    AIAgent: z.string().nullable().describe(`
        * * Field Name: AIAgent
        * * Display Name: AI Agent Name
        * * SQL Data Type: nvarchar(255)`),
    AISkill: z.string().nullable().describe(`
        * * Field Name: AISkill
        * * Display Name: AI Skill
        * * SQL Data Type: nvarchar(255)`),
});

export type MJSearchExecutionLogEntityType = z.infer<typeof MJSearchExecutionLogSchema>;

/**
 * zod schema definition for the entity MJ: Search Providers
 */
export const MJSearchProviderSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    Name: z.string().describe(`
        * * Field Name: Name
        * * Display Name: Name
        * * SQL Data Type: nvarchar(200)
        * * Description: Display name for this search provider (e.g., "Vector Search", "Algolia")`),
    Description: z.string().nullable().describe(`
        * * Field Name: Description
        * * Display Name: Description
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Human-readable description of what this provider searches and how it works`),
    DriverClass: z.string().describe(`
        * * Field Name: DriverClass
        * * Display Name: Driver Class
        * * SQL Data Type: nvarchar(500)
        * * Description: ClassFactory key used with @RegisterClass(ISearchProvider, DriverClass) to instantiate the provider at runtime`),
    Status: z.union([z.literal('Active'), z.literal('Pending'), z.literal('Terminated')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Active
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Pending
    *   * Terminated
        * * Description: Provider lifecycle status: Pending (not yet activated), Active (in use), Terminated (disabled)`),
    Priority: z.number().describe(`
        * * Field Name: Priority
        * * Display Name: Priority
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Execution priority (lower = higher priority). Controls provider ordering and can influence RRF weighting. Must be >= 0.`),
    SupportsPreview: z.boolean().describe(`
        * * Field Name: SupportsPreview
        * * Display Name: Supports Preview
        * * SQL Data Type: bit
        * * Default Value: 1
        * * Description: Whether this provider should run during fast preview/autocomplete searches. Expensive providers (external APIs) may set this to 0.`),
    MaxResultsOverride: z.number().nullable().describe(`
        * * Field Name: MaxResultsOverride
        * * Display Name: Max Results Override
        * * SQL Data Type: int
        * * Description: Optional per-provider cap on the number of results to return. Useful for rate-limited or pay-per-query external APIs. When NULL, uses the SearchEngine default.`),
    ProviderConfig: z.string().nullable().describe(`
        * * Field Name: ProviderConfig
        * * Display Name: Provider Configuration
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional JSON configuration blob for provider-specific settings (e.g., API endpoints, index names, tuning parameters). Schema is provider-defined.`),
    CredentialID: z.string().nullable().describe(`
        * * Field Name: CredentialID
        * * Display Name: Credential
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Credentials (vwCredentials.ID)
        * * Description: Optional FK to the Credential entity for providers that require authentication (e.g., Algolia API key, external service credentials)`),
    DisplayName: z.string().nullable().describe(`
        * * Field Name: DisplayName
        * * Display Name: Display Name
        * * SQL Data Type: nvarchar(200)
        * * Description: UI display name for this provider shown in filter facets and result grouping (e.g., "Database", "Semantic Search"). When NULL, falls back to the Name column.`),
    Icon: z.string().nullable().describe(`
        * * Field Name: Icon
        * * Display Name: Icon
        * * SQL Data Type: nvarchar(200)
        * * Description: CSS icon class for UI display in filter facets and result badges (e.g., "fa-solid fa-database", "fa-solid fa-brain"). Supports any CSS-based icon library. When NULL, a default icon is used.`),
    Comments: z.string().nullable().describe(`
        * * Field Name: Comments
        * * Display Name: Comments
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Free-form notes about this provider configuration`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    Credential: z.string().nullable().describe(`
        * * Field Name: Credential
        * * Display Name: Credential Name
        * * SQL Data Type: nvarchar(200)`),
});

export type MJSearchProviderEntityType = z.infer<typeof MJSearchProviderSchema>;

/**
 * zod schema definition for the entity MJ: Search Scope Entities
 */
export const MJSearchScopeEntitySchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    SearchScopeID: z.string().describe(`
        * * Field Name: SearchScopeID
        * * Display Name: Search Scope ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Search Scopes (vwSearchScopes.ID)`),
    EntityID: z.string().describe(`
        * * Field Name: EntityID
        * * Display Name: Entity ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Entities (vwEntities.ID)`),
    ExtraFilter: z.string().nullable().describe(`
        * * Field Name: ExtraFilter
        * * Display Name: Extra Filter
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional SQL filter applied to this entity's search within this scope. Example: Status='Published' AND DepartmentID='abc'. Rendered as a Nunjucks template with SearchContext variables for multi-tenant filtering.`),
    UserSearchString: z.string().nullable().describe(`
        * * Field Name: UserSearchString
        * * Display Name: User Search String
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional override for the UserSearchString passed to RunView for this entity within this scope. Nunjucks template (e.g., "{{ query }} AND type:policy"). NULL = pass the user's actual query through as-is.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    RequiredMetadataKeys: z.string().nullable().describe(`
        * * Field Name: RequiredMetadataKeys
        * * Display Name: Required Metadata Keys
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON array of column or alias names the rendered ExtraFilter MUST reference for this lane to be considered safe, e.g. ["OrganizationID","ContentSourceID"]. Checked against the RENDERED filter at search time: if one is missing the lane is SKIPPED rather than queried, because a partially-rendered filter (an {% if %} clause dropped when its dimension was absent or discarded) is still valid SQL and silently widens the search. Same concept and same engine check as SearchScopeExternalIndex.RequiredMetadataKeys, applied to the SQL lane. NULL = no contract declared, which is the pre-migration behaviour.`),
    SearchScope: z.string().nullable().describe(`
        * * Field Name: SearchScope
        * * Display Name: Search Scope
        * * SQL Data Type: nvarchar(200)`),
    Entity: z.string().nullable().describe(`
        * * Field Name: Entity
        * * Display Name: Entity
        * * SQL Data Type: nvarchar(255)`),
});

export type MJSearchScopeEntityEntityType = z.infer<typeof MJSearchScopeEntitySchema>;

/**
 * zod schema definition for the entity MJ: Search Scope External Indexes
 */
export const MJSearchScopeExternalIndexSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    SearchScopeID: z.string().describe(`
        * * Field Name: SearchScopeID
        * * Display Name: Search Scope ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Search Scopes (vwSearchScopes.ID)`),
    IndexType: z.union([z.literal('AzureAISearch'), z.literal('Elasticsearch'), z.literal('OpenSearch'), z.literal('Other'), z.literal('Typesense'), z.literal('Vector')]).describe(`
        * * Field Name: IndexType
        * * Display Name: Index Type
        * * SQL Data Type: nvarchar(40)
        * * Default Value: Vector
    * * Value List Type: List
    * * Possible Values 
    *   * AzureAISearch
    *   * Elasticsearch
    *   * OpenSearch
    *   * Other
    *   * Typesense
    *   * Vector
        * * Description: Discriminator. Determines which provider class consumes this row: Vector | Elasticsearch | Typesense | AzureAISearch | OpenSearch | Other.`),
    VectorIndexID: z.string().nullable().describe(`
        * * Field Name: VectorIndexID
        * * Display Name: Vector Index ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Vector Indexes (vwVectorIndexes.ID)
        * * Description: FK to VectorIndex. REQUIRED when IndexType='Vector'. NULL for all other IndexType values.`),
    ExternalIndexName: z.string().nullable().describe(`
        * * Field Name: ExternalIndexName
        * * Display Name: External Index Name
        * * SQL Data Type: nvarchar(400)
        * * Description: For non-vector IndexTypes: the remote engine's index/collection/alias name (e.g., Elasticsearch index "kb_docs_v3", Typesense collection "articles"). NULL for IndexType='Vector' (VectorIndexID resolves the name instead).`),
    ExternalIndexConfig: z.string().nullable().describe(`
        * * Field Name: ExternalIndexConfig
        * * Display Name: External Index Config
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON with extra connection/config hints the provider needs (cluster alias, routing key, custom analyzer, etc.). Provider-interpreted.`),
    MetadataFilter: z.string().nullable().describe(`
        * * Field Name: MetadataFilter
        * * Display Name: Metadata Filter
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON filter expression applied as a native metadata filter on the remote engine. Pinecone/Qdrant/PGVector metadata filter, or Elasticsearch filter DSL, etc. Rendered as a Nunjucks template so SearchContext.PrimaryScopeRecordID and SearchContext.SecondaryScopes.* can be interpolated for multi-tenant filtering.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    RequiredMetadataKeys: z.string().nullable().describe(`
        * * Field Name: RequiredMetadataKeys
        * * Display Name: Required Metadata Keys
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON array of metadata key names the rendered MetadataFilter MUST constrain on for this lane to be considered safe, e.g. ["OrganizationID","ContentSourceID"]. Checked against the RENDERED filter at search time: if a key is missing the lane is SKIPPED rather than queried, because a partially-rendered filter silently widens the search. This also documents the ingest contract — these are the labels the writer must stamp on every document in the index, since a filter on a key that was never written either matches nothing or (on providers that ignore unknown keys) matches everything. NULL = no contract declared, which is the pre-migration behaviour.`),
    SearchScope: z.string().nullable().describe(`
        * * Field Name: SearchScope
        * * Display Name: Search Scope
        * * SQL Data Type: nvarchar(200)`),
    VectorIndex: z.string().nullable().describe(`
        * * Field Name: VectorIndex
        * * Display Name: Vector Index
        * * SQL Data Type: nvarchar(255)`),
});

export type MJSearchScopeExternalIndexEntityType = z.infer<typeof MJSearchScopeExternalIndexSchema>;

/**
 * zod schema definition for the entity MJ: Search Scope Permissions
 */
export const MJSearchScopePermissionSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()
        * * Description: Primary key. Auto-generated.`),
    SearchScopeID: z.string().describe(`
        * * Field Name: SearchScopeID
        * * Display Name: Search Scope
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Search Scopes (vwSearchScopes.ID)
        * * Description: The SearchScope this permission row applies to.`),
    UserID: z.string().nullable().describe(`
        * * Field Name: UserID
        * * Display Name: User
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Users (vwUsers.ID)
        * * Description: The user this permission applies to. Mutually exclusive with RoleID — exactly one must be set.`),
    RoleID: z.string().nullable().describe(`
        * * Field Name: RoleID
        * * Display Name: Role
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Roles (vwRoles.ID)
        * * Description: The role this permission applies to. Mutually exclusive with UserID — exactly one must be set. Permissions granted via roles flow to all users in that role.`),
    PermissionLevel: z.union([z.literal('Manage'), z.literal('None'), z.literal('Read'), z.literal('Search')]).describe(`
        * * Field Name: PermissionLevel
        * * Display Name: Permission Level
        * * SQL Data Type: nvarchar(20)
    * * Value List Type: List
    * * Possible Values 
    *   * Manage
    *   * None
    *   * Read
    *   * Search
        * * Description: Capability granted on this SearchScope. None = explicit deny (overrides role grants), Read = view scope metadata, Search = invoke ScopedSearchAction, Manage = full edit including authoring of permission rows. The resolver picks the highest level when multiple grants apply (direct + role).`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    StartAt: z.date().nullable().describe(`
        * * Field Name: StartAt
        * * Display Name: Start At
        * * SQL Data Type: datetimeoffset
        * * Description: Optional start of the window in which this grant applies. NULL = no lower bound. SearchScopePermission was the only member of this family without a time window, so temporary grants previously needed a bespoke mechanism.`),
    EndAt: z.date().nullable().describe(`
        * * Field Name: EndAt
        * * Display Name: End At
        * * SQL Data Type: datetimeoffset
        * * Description: Optional end of the window in which this grant applies. NULL = no upper bound.`),
    PrimaryScopeRecordID: z.string().nullable().describe(`
        * * Field Name: PrimaryScopeRecordID
        * * Display Name: Primary Scope Record ID
        * * SQL Data Type: uniqueidentifier
        * * Description: Optional tenant this grant is limited to, matched against SearchContext.PrimaryScopeRecordID at search time and type-checkable against the scope's own PrimaryScopeEntityID. NULL = applies to every tenant, which is the pre-migration behaviour for all existing rows. Deliberately NOT called OrganizationID: MJ is domain-agnostic and a scope's primary scope may be a Company, Client or Practice, so this reuses the existing primary-scope concept rather than inventing a parallel tenancy column.`),
    SearchScope: z.string().nullable().describe(`
        * * Field Name: SearchScope
        * * Display Name: Search Scope Name
        * * SQL Data Type: nvarchar(200)`),
    User: z.string().nullable().describe(`
        * * Field Name: User
        * * Display Name: User Name
        * * SQL Data Type: nvarchar(100)`),
    Role: z.string().nullable().describe(`
        * * Field Name: Role
        * * Display Name: Role Name
        * * SQL Data Type: nvarchar(50)`),
});

export type MJSearchScopePermissionEntityType = z.infer<typeof MJSearchScopePermissionSchema>;

