/**
 * zod schema definition for the entity MJ: Tags
 */
export const MJTagSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    Name: z.string().describe(`
        * * Field Name: Name
        * * Display Name: Name
        * * SQL Data Type: nvarchar(255)`),
    ParentID: z.string().nullable().describe(`
        * * Field Name: ParentID
        * * Display Name: Parent
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Tags (vwTags.ID)`),
    DisplayName: z.string().describe(`
        * * Field Name: DisplayName
        * * Display Name: Display Name
        * * SQL Data Type: nvarchar(255)
        * * Description: Field DisplayName for entity Tags.`),
    Description: z.string().nullable().describe(`
        * * Field Name: Description
        * * Display Name: Description
        * * SQL Data Type: nvarchar(MAX)`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    Status: z.union([z.literal('Active'), z.literal('Deleted'), z.literal('Deprecated'), z.literal('Merged')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Active
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Deleted
    *   * Deprecated
    *   * Merged
        * * Description: Lifecycle status of the tag: Active (in use), Merged (consolidated into another tag), Deprecated (no longer assigned but preserved), Deleted (soft-deleted).`),
    MergedIntoTagID: z.string().nullable().describe(`
        * * Field Name: MergedIntoTagID
        * * Display Name: Merged Into
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Tags (vwTags.ID)
        * * Description: When Status is Merged, points to the surviving tag this tag was merged into. All TaggedItem and ContentItemTag references are re-pointed during merge.`),
    IsGlobal: z.boolean().describe(`
        * * Field Name: IsGlobal
        * * Display Name: Is Global
        * * SQL Data Type: bit
        * * Default Value: 1
        * * Description: When 1, the tag is visible to every tenant/scope. When 0, the tag is only visible to the (Entity, Record) pairs listed in TagScope. Cannot be set together with TagScope rows — enforced in entity Save() override.`),
    AllowAutoGrow: z.boolean().describe(`
        * * Field Name: AllowAutoGrow
        * * Display Name: Allow Auto Grow
        * * SQL Data Type: bit
        * * Default Value: 1
        * * Description: When 1, the autotagger may auto-create new child tags under this node when running in AutoGrow or FreeFlow mode. When 0, new children must come through the TagSuggestion review queue.`),
    IsFrozen: z.boolean().describe(`
        * * Field Name: IsFrozen
        * * Display Name: Is Frozen
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: When 1, this subtree is locked: no new children may be created under this node or any descendant, regardless of taxonomy mode. Existing children remain editable.`),
    MaxChildren: z.number().nullable().describe(`
        * * Field Name: MaxChildren
        * * Display Name: Max Children
        * * SQL Data Type: int
        * * Description: Optional cap on the number of direct children allowed under this tag. NULL = unlimited. Auto-grow is blocked once this cap is reached and routed to the TagSuggestion queue.`),
    MaxDescendantDepth: z.number().nullable().describe(`
        * * Field Name: MaxDescendantDepth
        * * Display Name: Max Descendant Depth
        * * SQL Data Type: int
        * * Description: Optional cap on the depth of the subtree rooted at this tag. NULL = unlimited. 0 = leaf-only (no children at all). Enforced via ancestor walk during auto-grow.`),
    MinWeight: z.number().nullable().describe(`
        * * Field Name: MinWeight
        * * Display Name: Min Weight
        * * SQL Data Type: decimal(3, 2)
        * * Description: Optional minimum classifier confidence (0.00-1.00) required for this tag to be applied. Items below this floor are routed to the TagSuggestion queue instead of being tagged.`),
    RequiresReview: z.boolean().describe(`
        * * Field Name: RequiresReview
        * * Display Name: Requires Review
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: When 1, every classifier-applied use of this tag is routed to the TagSuggestion queue for human approval before being persisted as a ContentItemTag → TaggedItem.`),
    EmbeddingVector: z.string().nullable().describe(`
        * * Field Name: EmbeddingVector
        * * Display Name: Embedding Vector
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON-encoded numeric vector representing the tag's embedding under the model identified by EmbeddingModelID. Refreshed automatically on Save() when Name or Description changes. Used to seed the in-memory tag vector cache without a cold-start LLM round-trip.`),
    EmbeddingModelID: z.string().nullable().describe(`
        * * Field Name: EmbeddingModelID
        * * Display Name: Embedding Model
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: AI Models (vwAIModels.ID)
        * * Description: AI model whose embedding produced EmbeddingVector. When the configured tag-embedding model differs from this value, the cached vector is treated as stale and recomputed.`),
    EmbeddingVectorBinary: z.string().nullable().describe(`
        * * Field Name: EmbeddingVectorBinary
        * * Display Name: Embedding Vector Binary
        * * SQL Data Type: varbinary(MAX)
        * * Description: The tag embedding as little-endian IEEE-754 float32 bytes (4 bytes per dimension): the compact form of EmbeddingVector. Written alongside EmbeddingVector; readers prefer it and fall back to EmbeddingVector when it is NULL.`),
    Parent: z.string().nullable().describe(`
        * * Field Name: Parent
        * * Display Name: Parent Name
        * * SQL Data Type: nvarchar(255)`),
    MergedIntoTag: z.string().nullable().describe(`
        * * Field Name: MergedIntoTag
        * * Display Name: Merged Into Name
        * * SQL Data Type: nvarchar(255)`),
    EmbeddingModel: z.string().nullable().describe(`
        * * Field Name: EmbeddingModel
        * * Display Name: Embedding Model Name
        * * SQL Data Type: nvarchar(50)`),
    RootParentID: z.string().nullable().describe(`
        * * Field Name: RootParentID
        * * Display Name: Root Parent
        * * SQL Data Type: uniqueidentifier`),
    ParentIDDepth: z.number().nullable().describe(`
        * * Field Name: ParentIDDepth
        * * Display Name: Parent ID Depth
        * * SQL Data Type: int`),
    ParentIDPath: z.string().nullable().describe(`
        * * Field Name: ParentIDPath
        * * Display Name: Parent ID Path
        * * SQL Data Type: nvarchar(MAX)`),
    ParentIDIsLeaf: z.boolean().nullable().describe(`
        * * Field Name: ParentIDIsLeaf
        * * Display Name: Parent ID Is Leaf
        * * SQL Data Type: bit`),
    ParentIDChildCount: z.number().nullable().describe(`
        * * Field Name: ParentIDChildCount
        * * Display Name: Parent ID Child Count
        * * SQL Data Type: int`),
});

export type MJTagEntityType = z.infer<typeof MJTagSchema>;

/**
 * zod schema definition for the entity MJ: Task Dependencies
 */
export const MJTaskDependencySchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    TaskID: z.string().describe(`
        * * Field Name: TaskID
        * * Display Name: Task
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Tasks (vwTasks.ID)`),
    DependsOnTaskID: z.string().describe(`
        * * Field Name: DependsOnTaskID
        * * Display Name: Depends On Task ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Tasks (vwTasks.ID)`),
    DependencyType: z.union([z.literal('Corequisite'), z.literal('Optional'), z.literal('Prerequisite')]).describe(`
        * * Field Name: DependencyType
        * * Display Name: Dependency Type
        * * SQL Data Type: nvarchar(50)
        * * Default Value: Prerequisite
    * * Value List Type: List
    * * Possible Values 
    *   * Corequisite
    *   * Optional
    *   * Prerequisite
        * * Description: Type of dependency relationship (Prerequisite, Corequisite, Optional)`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    Condition: z.string().nullable().describe(`
        * * Field Name: Condition
        * * Display Name: Condition
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional boolean expression gating this dependency edge. NULL (the default, and the value every pre-existing row carries) means the edge is unconditional, so adding this column changes the meaning of no existing graph. When present it is evaluated by the shared GraphTraversalEngine against the same context a design-time AIAgentStepPath.Condition sees, which is what lets a runtime task graph and a flow-editor graph be the same graph. A condition that evaluates false skips the edge; one that fails to evaluate ALSO skips it, but is reported distinctly so a graph stalled by a malformed expression cannot be mistaken for one that finished normally.`),
    Priority: z.number().describe(`
        * * Field Name: Priority
        * * Display Name: Priority
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Ordering within an exclusive group — higher wins. Mirrors AIAgentStepPath.Priority so a compiled workflow chooses the same branch the flow editor shows. Ignored for edges that are not part of an ExclusiveGroup.`),
    Sequence: z.number().describe(`
        * * Field Name: Sequence
        * * Display Name: Sequence
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Deterministic tiebreak when two edges in an ExclusiveGroup share a Priority, applied ascending. Load-bearing rather than cosmetic: compiled dependencies get fresh UUIDs and Priority defaults to 0, so without a stored ordinal a tie would resolve by row order and the same workflow could take a different branch on a different machine.`),
    ExclusiveGroup: z.string().nullable().describe(`
        * * Field Name: ExclusiveGroup
        * * Display Name: Exclusive Group
        * * SQL Data Type: nvarchar(255)
        * * Description: XOR group key: sibling edges leaving the same origin that share a non-null ExclusiveGroup are an exclusive fan-out. The highest-Priority satisfied edge wins, ties broken by ascending Sequence; the rest are Skipped. NULL (the default) means an ordinary dependency, so existing graphs are unaffected. An unevaluable condition anywhere in the group holds the whole group rather than firing every branch.`),
    Task: z.string().nullable().describe(`
        * * Field Name: Task
        * * Display Name: Task Name
        * * SQL Data Type: nvarchar(255)`),
    DependsOnTask: z.string().nullable().describe(`
        * * Field Name: DependsOnTask
        * * Display Name: Depends On Task Name
        * * SQL Data Type: nvarchar(255)`),
});

export type MJTaskDependencyEntityType = z.infer<typeof MJTaskDependencySchema>;

