/**
 * zod schema definition for the entity MJ: Tests
 */
export const MJTestSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    TypeID: z.string().describe(`
        * * Field Name: TypeID
        * * Display Name: Test Type
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Test Types (vwTestTypes.ID)
        * * Description: Foreign Key - The type of test (e.g., Agent Eval, Workflow Test). Determines which driver class handles execution.`),
    Name: z.string().describe(`
        * * Field Name: Name
        * * Display Name: Name
        * * SQL Data Type: nvarchar(255)
        * * Description: Name of the test (e.g., "Pie Chart with Drilldown", "Memory Recall Accuracy")`),
    Description: z.string().nullable().describe(`
        * * Field Name: Description
        * * Display Name: Description
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Detailed description of what this test validates and why it matters`),
    Status: z.union([z.literal('Active'), z.literal('Disabled'), z.literal('Pending')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Active
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Disabled
    *   * Pending
        * * Description: Status of the test: Pending (being configured), Active (ready to run), Disabled (archived/not in use)`),
    InputDefinition: z.string().nullable().describe(`
        * * Field Name: InputDefinition
        * * Display Name: Input Definition
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON object defining the inputs/parameters for the test. Structure varies by test type (e.g., for Agent Eval: {prompt, context, conversationHistory})`),
    ExpectedOutcomes: z.string().nullable().describe(`
        * * Field Name: ExpectedOutcomes
        * * Display Name: Expected Outcomes
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON object defining what success looks like. Structure varies by test type (e.g., for Agent Eval: {toolCalls, outputFormat, semanticGoals, dataAssertions})`),
    Configuration: z.any().nullable().describe(`
        * * Field Name: Configuration
        * * Display Name: Configuration
        * * SQL Data Type: nvarchar(MAX)
        * * JSON Type: MJTestEntity_ITestConfiguration
        * * Description: JSON object for test-specific configuration (e.g., oracles to use, rubrics, retry policies, timeout settings)`),
    Tags: z.string().nullable().describe(`
        * * Field Name: Tags
        * * Display Name: Tags
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON array of tags for categorization and filtering (e.g., ["smoke", "agent-quality", "performance"])`),
    Priority: z.number().nullable().describe(`
        * * Field Name: Priority
        * * Display Name: Priority
        * * SQL Data Type: int
        * * Default Value: 0
        * * Description: Priority for execution ordering. Lower numbers run first. Useful for dependencies or critical path tests.`),
    EstimatedDurationSeconds: z.number().nullable().describe(`
        * * Field Name: EstimatedDurationSeconds
        * * Display Name: Estimated Duration (seconds)
        * * SQL Data Type: int
        * * Description: Estimated execution time in seconds. Used for scheduling and timeout calculations.`),
    EstimatedCostUSD: z.number().nullable().describe(`
        * * Field Name: EstimatedCostUSD
        * * Display Name: Estimated Cost (USD)
        * * SQL Data Type: decimal(10, 6)
        * * Description: Estimated cost in USD for running this test (e.g., LLM token costs, compute resources). Used for budgeting and optimization.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    RepeatCount: z.number().nullable().describe(`
        * * Field Name: RepeatCount
        * * Display Name: Repeat Count
        * * SQL Data Type: int
        * * Description: Number of times to repeat this test execution. NULL or 1 = single execution. Values > 1 will create multiple test runs for statistical analysis.`),
    MaxExecutionTimeMS: z.number().nullable().describe(`
        * * Field Name: MaxExecutionTimeMS
        * * Display Name: Max Execution Time (ms)
        * * SQL Data Type: int
        * * Description: Maximum execution time in milliseconds for this test. If NULL, uses default (300000ms = 5 minutes). Can be overridden by Configuration JSON maxExecutionTime field for backward compatibility.`),
    Variables: z.string().nullable().describe(`
        * * Field Name: Variables
        * * Display Name: Variables
        * * SQL Data Type: nvarchar(MAX)
        * * Description: JSON configuration for which test type variables are exposed by this test, along with test-level defaults, locks, and value restrictions. References variables defined in the parent TestType.VariablesSchema.`),
    RubricID: z.string().nullable().describe(`
        * * Field Name: RubricID
        * * Display Name: Rubric ID
        * * SQL Data Type: uniqueidentifier
        * * Related Entity/Foreign Key: MJ: Rubrics (vwRubrics.ID)
        * * Description: The rubric this test's output is judged by. NULL = inherit from the suite (walking up ParentID). The latest published version is pinned when each run starts.`),
    Type: z.string().nullable().describe(`
        * * Field Name: Type
        * * Display Name: Type
        * * SQL Data Type: nvarchar(100)`),
    Rubric: z.string().nullable().describe(`
        * * Field Name: Rubric
        * * Display Name: Rubric
        * * SQL Data Type: nvarchar(255)`),
});

export type MJTestEntityType = z.infer<typeof MJTestSchema>;

/**
 * zod schema definition for the entity MJ: Themes
 */
export const MJThemeSchema = z.object({
    ID: z.string().describe(`
        * * Field Name: ID
        * * Display Name: ID
        * * SQL Data Type: uniqueidentifier
        * * Default Value: newsequentialid()`),
    Name: z.string().describe(`
        * * Field Name: Name
        * * Display Name: Name
        * * SQL Data Type: nvarchar(100)
        * * Description: Display name for the theme (unique).`),
    Description: z.string().nullable().describe(`
        * * Field Name: Description
        * * Display Name: Description
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional description of the theme.`),
    Seeds: z.string().describe(`
        * * Field Name: Seeds
        * * Display Name: Seeds
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Brand seeds as JSON (the ThemeSeeds shape from @memberjunction/theme-engine): primary/accent/tertiary hue anchors, neutralChroma, vibrancy, radius, depth, fontFamily, and an optional vizPalette override. Source of truth — the full token contract is derived from this, not stored.`),
    LightMarkURL: z.string().nullable().describe(`
        * * Field Name: LightMarkURL
        * * Display Name: Light Mode Logo
        * * SQL Data Type: nvarchar(1000)
        * * Description: Public URL of the logo mark for light surfaces. Logos are variant uploads, never recolored.`),
    DarkMarkURL: z.string().nullable().describe(`
        * * Field Name: DarkMarkURL
        * * Display Name: Dark Mode Logo
        * * SQL Data Type: nvarchar(1000)
        * * Description: Public URL of the logo mark for dark surfaces. Dark mode swaps to this artwork rather than transforming the light mark.`),
    WordmarkURL: z.string().nullable().describe(`
        * * Field Name: WordmarkURL
        * * Display Name: Wordmark Logo
        * * SQL Data Type: nvarchar(1000)
        * * Description: Optional public URL of the full wordmark logo.`),
    MonochromeURL: z.string().nullable().describe(`
        * * Field Name: MonochromeURL
        * * Display Name: Monochrome Logo
        * * SQL Data Type: nvarchar(1000)
        * * Description: Optional public URL of a single-fill monochrome logo variant.`),
    IsDefault: z.boolean().describe(`
        * * Field Name: IsDefault
        * * Display Name: Is Default Theme
        * * SQL Data Type: bit
        * * Default Value: 0
        * * Description: When 1, this is the default theme applied when no other is selected. Single-default enforcement is handled at the application layer.`),
    Status: z.union([z.literal('Active'), z.literal('Draft'), z.literal('Inactive')]).describe(`
        * * Field Name: Status
        * * Display Name: Status
        * * SQL Data Type: nvarchar(20)
        * * Default Value: Active
    * * Value List Type: List
    * * Possible Values 
    *   * Active
    *   * Draft
    *   * Inactive
        * * Description: Lifecycle status: Active (available), Inactive (retired), or Draft (in progress, not applied).`),
    Overrides: z.string().nullable().describe(`
        * * Field Name: Overrides
        * * Display Name: Token Overrides
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional advanced token overrides as a JSON object mapping a --mj-* CSS custom property name to a value (e.g. {"--mj-brand-primary-hover":"#0a5cff"}). Applied on top of the seed-derived token contract at load, before CustomCSS. Leave null to use the pure derived theme.`),
    CustomCSS: z.string().nullable().describe(`
        * * Field Name: CustomCSS
        * * Display Name: Custom CSS
        * * SQL Data Type: nvarchar(MAX)
        * * Description: Optional advanced raw CSS appended to the theme overlay and auto-scoped under [data-theme-overlay="<id>"]. Applied last, after the derived tokens and Overrides. Escape hatch for rules the seed/token model cannot express; leave null for none.`),
    __mj_CreatedAt: z.date().describe(`
        * * Field Name: __mj_CreatedAt
        * * Display Name: Created At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    __mj_UpdatedAt: z.date().describe(`
        * * Field Name: __mj_UpdatedAt
        * * Display Name: Updated At
        * * SQL Data Type: datetimeoffset
        * * Default Value: getutcdate()`),
    LoginScreen: z.string().nullable().describe(`
        * * Field Name: LoginScreen
        * * Display Name: Login Screen
        * * SQL Data Type: nvarchar(MAX)
        * * Description: The published sign-in page design as JSON (the LoginDesign shape from @memberjunction/theme-engine): layout, background, colors and the blocks in each login-screen region. The default Active theme's value is served unauthenticated to draw the Explorer login screen. NULL means the stock login screen.`),
    LoginScreenDraft: z.string().nullable().describe(`
        * * Field Name: LoginScreenDraft
        * * Display Name: Login Screen Draft
        * * SQL Data Type: nvarchar(MAX)
        * * Description: The sign-in page design being edited in Login Studio, as JSON in the same shape as LoginScreen. Never served publicly; publishing copies it to LoginScreen. NULL means no draft.`),
});

export type MJThemeEntityType = z.infer<typeof MJThemeSchema>;

